// Normalize RD VAT SOAP response with error handling
const allItems = $input.all();
const data = Array.isArray(allItems[0]?.json) ? allItems[0].json : allItems.map(i => i.json ?? {});

function clean(val) {
  const x = String(val ?? '').trim();
  return x === '-' ? '' : x;
}

function getField(obj, field) {
  const sr = obj?.["soap:Envelope"]?.["soap:Body"]?.ServiceResponse?.ServiceResult ?? {};
  const v = sr[field];
  if (v == null) return '';
  if (typeof v === 'string' || typeof v === 'number') return String(v);
  if (v.anyType !== undefined) {
    const a = v.anyType;
    if (typeof a === 'string' || typeof a === 'number') return String(a);
    if (a && typeof a._ !== 'undefined') return String(a._);
  }
  if (typeof v._ !== 'undefined') return String(v._);
  return '';
}

function parseError(obj) {
  const sr = obj?.["soap:Envelope"]?.["soap:Body"]?.ServiceResponse?.ServiceResult ?? {};
  return clean(sr.vmsgerr ?? obj.errorMessage ?? obj.error?.message ?? '');
}

const out = [];

data.forEach((item, index) => {
  const errMsg = parseError(item);
  const vatId = clean(getField(item, 'vNID'));

  const branchRaw = clean(getField(item, 'vBranchNumber'));
  const branchNumber = branchRaw === '0' || branchRaw === '' ? '00000' : branchRaw.padStart(5, '0');
  const branchLabel = branchNumber === '00000' ? '????????????' : `???? ${branchNumber}`;

  const titleName = clean(getField(item, 'vtitleName'));
  const companyNameMain = clean(getField(item, 'vName'));

  out.push({
    json: {
      vatId,
      companyName: `${titleName} ${companyNameMain}`.trim(),
      branch: {
        branchNumber,
        branchLabel,
        branchName: clean(getField(item, 'vBranchName')),
      },
      address: {
        houseNo: clean(getField(item, 'vHouseNumber')),
        moo: clean(getField(item, 'vMooNumber')),
        village: clean(getField(item, 'vVillageName')),
        building: clean(getField(item, 'vBuildingName')),
        floor: clean(getField(item, 'vFloorNumber')),
        room: clean(getField(item, 'vRoomNumber')),
        soi: clean(getField(item, 'vSoiName')),
        street: clean(getField(item, 'vStreetName')),
        subDistrict: clean(getField(item, 'vThambol')),
        district: clean(getField(item, 'vAmphur')),
        province: clean(getField(item, 'vProvince')),
        postcode: clean(getField(item, 'vPostCode')),
        yaek: clean(getField(item, 'vYaek')),
      },
      businessFirstDate: clean(getField(item, 'vBusinessFirstDate')),
      errorMessage: errMsg,
      success: Boolean(vatId && !errMsg),
    },
    pairedItem: { item: index },
  });
});

return out;

