// ดึงทุก item จาก input
const items = $input.all();

/**
 * สร้างที่อยู่แบบข้อความยาว (raw address) จาก object address
 */
function buildRawAddress(address) {
  if (!address) return "";

  const parts = [];

  // เลขที่บ้าน
  if (address.houseNo) parts.push(address.houseNo);

  // หมู่
  if (address.moo) parts.push("หมู่ " + address.moo);

  // หมู่บ้าน
  if (address.village) parts.push("หมู่บ้าน" + address.village);

  // อาคาร / ชั้น / ห้อง
  if (address.building) parts.push("อาคาร" + address.building);
  if (address.floor) parts.push("ชั้น " + address.floor);
  if (address.room) parts.push("ห้อง " + address.room);

  // ซอย / แยก / ถนน
  if (address.soi) parts.push("ซ." + address.soi);
  if (address.yaek) parts.push("แยก " + address.yaek);
  if (address.street) parts.push("ถ." + address.street);

  // แขวง/เขต หรือ ต./อ. (ถ้าไม่ใช่กรุงเทพ)
  const province = address.province || "";
  const isBangkok = /กรุงเทพมหานคร/.test(province);

  if (address.subDistrict) {
    parts.push((isBangkok ? "แขวง " : "ต.") + address.subDistrict);
  }

  if (address.district) {
    parts.push((isBangkok ? "เขต " : "อ.") + address.district);
  }

  // จังหวัด
  if (province) {
    if (isBangkok) {
      // กรุงเทพมหานคร ไม่ต้องใส่ "จ."
      parts.push(province);
    } else {
      // จังหวัดทั่วไป → เติม "จ."
      parts.push("จ." + province);
    }
  }

  // รหัสไปรษณีย์
  if (address.postcode) parts.push(address.postcode);

  // join และเก็บช่องว่างให้เรียบร้อย
  return parts.join(" ").replace(/\s+/g, " ").trim();
}

// แปลงทุก item แล้วเพิ่ม field address_raw
return items.map(item => {
  const data = item.json;
  const address = data.address || null;

  const raw = buildRawAddress(address);

  return {
    json: {
      ...data,
      address_raw: raw,  // 👉 ที่อยู่แบบ raw address พร้อม "จ.จังหวัด"
    },
  };
});
